/* @autogenerated */
package net.civeira.phylax.integrationtest.features.oauth.flow;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.util.Base64;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;

import io.quarkus.test.junit.QuarkusTest;
import io.restassured.response.Response;
import net.civeira.phylax.integrationtest.features.oauth.fixtures.OidcTestFixtures;

@Tag("oidc-flow")
@QuarkusTest
class PkceFlowTest extends OidcIntegrationTestBase {

  // --- helpers ---

  private static String randomVerifier() {
    byte[] bytes = new byte[32];
    new SecureRandom().nextBytes(bytes);
    return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
  }

  private static String s256Challenge(String verifier) {
    try {
      byte[] digest =
          MessageDigest.getInstance("SHA-256").digest(verifier.getBytes(StandardCharsets.US_ASCII));
      return Base64.getUrlEncoder().withoutPadding().encodeToString(digest);
    } catch (Exception e) {
      throw new RuntimeException(e);
    }
  }

  // --- tests ---

  /**
   * Happy path S256: el cliente genera un verifier aleatorio, calcula el challenge SHA-256 y lo
   * envía en /authorize. Al intercambiar el código con el verifier correcto obtiene el token.
   */
  @Test
  void pkce_s256_happyPath_returnsToken() {
    String verifier = randomVerifier();
    String challenge = s256Challenge(verifier);

    Response login = client.submitLoginWithPkce(OidcTestFixtures.TENANT, OidcTestFixtures.USERNAME,
        OidcTestFixtures.PASSWORD, null, challenge, "S256");
    String code = client.extractAuthCode(login);
    Assertions.assertNotNull(code, "Se esperaba un auth code en la respuesta");

    Response exchange = client.exchangeCodeWithVerifier(OidcTestFixtures.TENANT, code,
        OidcTestFixtures.REDIRECT_URI, OidcTestFixtures.CLIENT_ID, verifier);

    Assertions.assertEquals(200, exchange.statusCode());
    Assertions.assertNotNull(exchange.jsonPath().getString("access_token"));
  }

  /**
   * Verifier incorrecto con método S256: el challenge fue calculado para un verifier diferente.
   * El token endpoint debe rechazar con 401.
   */
  @Test
  void pkce_s256_wrongVerifier_returns401() {
    String verifier = randomVerifier();
    String challenge = s256Challenge(verifier);

    Response login = client.submitLoginWithPkce(OidcTestFixtures.TENANT, OidcTestFixtures.USERNAME,
        OidcTestFixtures.PASSWORD, null, challenge, "S256");
    String code = client.extractAuthCode(login);
    Assertions.assertNotNull(code);

    Response exchange = client.exchangeCodeWithVerifier(OidcTestFixtures.TENANT, code,
        OidcTestFixtures.REDIRECT_URI, OidcTestFixtures.CLIENT_ID, "wrong-verifier-xyz");

    Assertions.assertEquals(401, exchange.statusCode());
  }

  /**
   * Sin PKCE: un cliente confidencial que no envió code_challenge en /authorize puede intercambiar
   * el código sin code_verifier.
   */
  @Test
  void pkce_noPkce_confidentialClient_returnsToken() {
    Response login = client.submitLoginWithoutPkce(OidcTestFixtures.TENANT,
        OidcTestFixtures.USERNAME, OidcTestFixtures.PASSWORD, null);
    String code = client.extractAuthCode(login);
    Assertions.assertNotNull(code, "Se esperaba un auth code en la respuesta");

    Response exchange = client.exchangeCodeWithoutVerifier(OidcTestFixtures.TENANT, code,
        OidcTestFixtures.REDIRECT_URI, OidcTestFixtures.CLIENT_ID);

    Assertions.assertEquals(200, exchange.statusCode());
    Assertions.assertNotNull(exchange.jsonPath().getString("access_token"));
  }

  /**
   * Challenge S256 presentado como plain: enviar el verifier sin aplicar SHA-256 cuando el método
   * almacenado es S256. El hash calculado no coincide con el challenge → 401.
   */
  @Test
  void pkce_s256_verifierSentAsPlain_returns401() {
    String verifier = randomVerifier();
    String challenge = s256Challenge(verifier);

    Response login = client.submitLoginWithPkce(OidcTestFixtures.TENANT, OidcTestFixtures.USERNAME,
        OidcTestFixtures.PASSWORD, null, challenge, "S256");
    String code = client.extractAuthCode(login);
    Assertions.assertNotNull(code);

    // Se envía el challenge (no el verifier) como si fuera plain — debe fallar
    Response exchange = client.exchangeCodeWithVerifier(OidcTestFixtures.TENANT, code,
        OidcTestFixtures.REDIRECT_URI, OidcTestFixtures.CLIENT_ID, challenge);

    Assertions.assertEquals(401, exchange.statusCode());
  }
}
